// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type LaptopIconsProps = Record<string, any>;

// Shared exact SVG path definitions to ensure perfect alignment
const SVG_PATHS = {
  base: "M 20 220 L 280 220 A 10 10 0 0 1 290 230 L 290 240 A 10 10 0 0 1 280 250 L 20 250 A 10 10 0 0 1 10 240 L 10 230 A 10 10 0 0 1 20 220 Z",
  baseSlot: "M 130 235 L 170 235",
  screenOuter: "M 40 220 L 40 100 A 20 20 0 0 1 60 80 L 240 80 A 20 20 0 0 1 260 100 L 260 220",
  screenInner: "M 55 220 L 55 110 A 10 10 0 0 1 65 100 L 235 100 A 10 10 0 0 1 245 110 L 245 220",
  personBodyOutline: "M 90 220 C 90 170, 210 170, 210 220",
  personBodyFilled: "M 90 220 C 90 160, 210 160, 210 220 Z",
  bubble: "M230 70 h80 a20 20 0 0 1 20 20 v40 a20 20 0 0 1 -20 20 h-50 l-30 25 l10 -25 h-10 a20 20 0 0 1 -20 -20 v-40 a20 20 0 0 1 20 -20 z"
};

const LaptopIcon: React.FC<{
  variant: "outline" | "filled";
  primaryColor: string;
  surfaceColor: string;
  frame: number;
  fps: number;
  delay: number;
}> = ({ variant, primaryColor, surfaceColor, frame, fps, delay }) => {
  const isOutline = variant === "outline";

  // Staggered animation timing
  const iconStart = delay;
  const bubbleStart = delay + 15;
  const dotsStart = bubbleStart + 12;

  // Fluid motion physics
  const iconProgress = spring({
    frame: frame - iconStart,
    fps,
    config: { damping: 14, stiffness: 90 }
  });

  const bubbleProgress = spring({
    frame: frame - bubbleStart,
    fps,
    config: { damping: 12, stiffness: 150 }
  });

  // Sequential dot appearances
  const dot1Progress = spring({ frame: Math.max(0, frame - dotsStart), fps, config: { damping: 10, stiffness: 200 } });
  const dot2Progress = spring({ frame: Math.max(0, frame - (dotsStart + 6)), fps, config: { damping: 10, stiffness: 200 } });
  const dot3Progress = spring({ frame: Math.max(0, frame - (dotsStart + 12)), fps, config: { damping: 10, stiffness: 200 } });

  // Continuous subtle float
  const floatY = interpolate(Math.sin((frame + delay) / 20), [-1, 1], [-3, 3]);

  // Dynamic styling based on requested variant
  const strokeColor = primaryColor;
  const strokeW = isOutline ? 8 : 22;

  const bubbleFill = isOutline ? surfaceColor : primaryColor;
  const bubbleStroke = isOutline ? primaryColor : "none";
  const bubbleStrokeW = isOutline ? 8 : 0;

  const dotFill = isOutline ? primaryColor : surfaceColor;

  return (
    <div style={{
      width: 400,
      height: 300,
      transform: `scale(${iconProgress}) translateY(${floatY}px)`,
      opacity: interpolate(frame - iconStart, [0, 8], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
      position: 'relative',
      transition: "none"
    }}>
      <svg viewBox="0 0 400 300" style={{ width: '100%', height: '100%', overflow: 'visible' }}>
        
        {/* 1. Laptop Screen Frame */}
        <path
          d={SVG_PATHS.screenOuter}
          fill="none"
          stroke={strokeColor}
          strokeWidth={strokeW}
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {/* 2. Inner Screen Detail (Outline only) */}
        {isOutline && (
          <path
            d={SVG_PATHS.screenInner}
            fill="none"
            stroke={strokeColor}
            strokeWidth={4}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        )}

        {/* 3. Person Body */}
        <path
          d={isOutline ? SVG_PATHS.personBodyOutline : SVG_PATHS.personBodyFilled}
          fill={isOutline ? "none" : primaryColor}
          stroke={isOutline ? primaryColor : "none"}
          strokeWidth={isOutline ? 8 : 0}
          strokeLinecap="round"
        />

        {/* 4. Person Head */}
        <circle
          cx={150}
          cy={140}
          r={26}
          fill={isOutline ? "none" : primaryColor}
          stroke={isOutline ? primaryColor : "none"}
          strokeWidth={isOutline ? 8 : 0}
        />

        {/* 5. Laptop Base (Drawn over the bottom of screen/person for overlap) */}
        <path
          d={SVG_PATHS.base}
          fill={isOutline ? surfaceColor : primaryColor}
          stroke={isOutline ? primaryColor : "none"}
          strokeWidth={isOutline ? 8 : 0}
          strokeLinejoin="round"
        />
        
        {/* Base Notch Detail */}
        <path
          d={SVG_PATHS.baseSlot}
          fill="none"
          stroke={isOutline ? primaryColor : surfaceColor}
          strokeWidth={6}
          strokeLinecap="round"
        />

        {/* 6. Animated Speech Bubble Layer */}
        <g style={{
          transformOrigin: '210px 150px',
          transform: `scale(${bubbleProgress})`,
          opacity: interpolate(frame - bubbleStart, [0, 4], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })
        }}>
          <path
            d={SVG_PATHS.bubble}
            fill={bubbleFill}
            stroke={bubbleStroke}
            strokeWidth={bubbleStrokeW}
            strokeLinejoin="round"
          />
          
          {/* Sequentially Animated Dots */}
          <circle cx="255" cy="110" r="6.5" fill={dotFill}
                  style={{ transformOrigin: '255px 110px', transform: `scale(${dot1Progress})` }} />
          <circle cx="280" cy="110" r="6.5" fill={dotFill}
                  style={{ transformOrigin: '280px 110px', transform: `scale(${dot2Progress})` }} />
          <circle cx="305" cy="110" r="6.5" fill={dotFill}
                  style={{ transformOrigin: '305px 110px', transform: `scale(${dot3Progress})` }} />
        </g>
      </svg>
    </div>
  );
};

const LaptopIcons: React.FC<LaptopIconsProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  surfaceColor = "#ffffff",
  primaryColor = "#0f0f0f",
  durationInSeconds = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling to fit 16:9 canvas beautifully
  const containerScale = Math.min(width / 1100, height / 600);

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: interFamily, 
      justifyContent: 'center', 
      alignItems: 'center' 
    }}>
      <div style={{
        display: 'flex',
        flexDirection: 'row',
        gap: '80px',
        transform: `scale(${containerScale})`,
        transition: "none"
      }}>
        <LaptopIcon 
          variant="outline" 
          primaryColor={primaryColor} 
          surfaceColor={surfaceColor} 
          frame={frame} 
          fps={fps} 
          delay={10} 
        />
        <LaptopIcon 
          variant="filled" 
          primaryColor={primaryColor} 
          surfaceColor={surfaceColor} 
          frame={frame} 
          fps={fps} 
          delay={20} 
        />
      </div>
    </AbsoluteFill>
  );
};

export default LaptopIcons;